	if err != nil {
		return nil, err
	}
	defer closeParent()

	if before, err := parent.Lstat(leaf); err == nil {
		if before.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
		}
